<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import type {VoucherRecord} from '../voucher-analysis'
import {organizationLocation,straightLineKm} from '../voucher-profile'
const props=defineProps<{record:VoucherRecord;kind:'education'|'kindergarten'}>()
const selected=ref(0)
watch(()=>props.record,()=>{selected.value=Math.max(0,props.record.placements.length-1)},{immediate:true})
const profile=computed(()=>props.record.profile),placement=computed(()=>props.record.placements[selected.value]),organization=computed(()=>{const p=placement.value;return p?organizationLocation(p.inn,p.region,p.district):null}),distance=computed(()=>straightLineKm(profile.value?.home,organization.value))
const date=(value:string)=>value.split('-').reverse().join('.')
const map=(lat:number,lon:number)=>'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(lat+','+lon)
</script>
<template>
<section v-if="profile" class="voucher-profile" aria-label="Bola va qonuniy vakil xulosasi">
 <header><h3>Xulosa · bola va qonuniy vakil</h3><small>Namunaviy shaxsiy ma’lumotlar</small></header>
 <div class="vp-persons">
  <figure class="vp-photo"><svg viewBox="0 0 96 112" role="img" :aria-label="record.name+' · namunaviy bola rasmi'"><rect width="96" height="112" rx="10" fill="#e4f1eb"/><path d="M12 112v-15c0-22 72-22 72 0v15" fill="#3e8b6e"/><ellipse cx="48" cy="48" rx="24" ry="29" fill="#edc6a6"/><path d="M24 45c-8-42 60-43 48 0l-6-17c-11 12-24 4-31 5l-9 17" fill="#594537"/><circle cx="39" cy="48" r="2" fill="#493c34"/><circle cx="57" cy="48" r="2" fill="#493c34"/><path d="M41 62q7 6 14 0" fill="none" stroke="#ac725f" stroke-width="2"/></svg><figcaption>Rasm · namuna</figcaption></figure>
  <dl><div><dt>Bolaning FIO</dt><dd>{{ record.name }}</dd></div><div><dt>JSHSHIR</dt><dd>{{ record.pinfl }}</dd></div><div><dt>Tug‘ilgan sana / yosh</dt><dd>{{ date(profile.birth) }} · {{ record.age }} yosh</dd></div><div><dt>Reestrga kiritilgan sana</dt><dd class="vp-green">{{ date(profile.registryDate) }}</dd></div></dl>
  <dl><div><dt>Qonuniy vakil</dt><dd>{{ profile.guardian.name }}</dd></div><div><dt>Vakilning JSHSHIR</dt><dd>{{ profile.guardian.pinfl }}</dd></div><div><dt>Telefon raqami</dt><dd>{{ profile.guardian.phone }}</dd></div><div><dt>Yashash manzili</dt><dd>{{ profile.home.region }} · {{ profile.home.district }}<small>{{ profile.home.address }}</small></dd></div></dl>
 </div>
 <section v-if="kind==='education'" class="vp-locations" aria-label="Yashash va to‘garak lokatsiyalari">
  <header><h3>Yashash joyi → to‘garak</h3><label v-if="record.placements.length">Qatnov joyi<select v-model.number="selected" aria-label="Lokatsiya bo‘yicha tashkilot tarixi"><option v-for="(p,i) in record.placements" :key="i" :value="i">{{ date(p.entered) }} · {{ p.organization }} · {{ p.subject }}</option></select></label></header>
  <div class="vp-location-grid">
   <article><span class="vp-dot home"></span><h4>Yashash joyi</h4><b>{{ profile.home.region }} · {{ profile.home.district }}</b><p>{{ profile.home.address }}</p><a v-if="profile.home.lat!==null&&profile.home.lon!==null" :href="map(profile.home.lat,profile.home.lon)" target="_blank" rel="noopener noreferrer">{{ profile.home.lat.toFixed(5) }}, {{ profile.home.lon.toFixed(5) }} ↗</a><small v-else>Koordinatalar kelmagan</small></article>
   <article class="vp-distance"><span>Oraliq masofa</span><strong>{{ distance===null?'—':distance.toLocaleString('uz-UZ')+' km' }}</strong><small>To‘g‘ri chiziq bo‘yicha</small><small>Yo‘l masofasi: manba yo‘q</small></article>
   <article><span class="vp-dot org"></span><h4>To‘garak tashkiloti</h4><template v-if="placement"><b>{{ placement.organization }} ({{ placement.inn }})</b><p>{{ placement.region }} · {{ placement.district }}<br>{{ organization?.address??'Aniq manzil kelmagan' }}</p><a v-if="organization?.lat!==null&&organization?.lon!==null&&organization" :href="map(organization.lat,organization.lon)" target="_blank" rel="noopener noreferrer">{{ organization.lat.toFixed(5) }}, {{ organization.lon.toFixed(5) }} ↗</a><small v-else>Koordinatalar kelmagan</small><small>{{ placement.subject }} · Kirish: {{ date(placement.entered) }}{{ placement.left?' · Chiqish: '+date(placement.left):'' }}</small></template><p v-else>Faollashtirish xabari kutilmoqda. Tashkilot va fan hali belgilanmagan.</p></article>
  </div>
  <p class="vp-location-note">Lokatsiyalar namunaviy. Masofa yo‘lkira huquqi yoki to‘lovini belgilash uchun qo‘llanilmaydi. Tashkilot o‘zgarsa ham vaucherning dastlabki amal muddati saqlanadi.</p>
 </section>
</section>
</template>
